  function getAuctionPriceFieldName(meatGrade) {
    const cleanGrade = meatGrade.replace(/\s+/g, "").toUpperCase();
    const gradeTagMap = {
      "1++A": "auct_0aAmt",
      "1++B": "auct_0bAmt",
      "1++C": "auct_0cAmt",
      "1+A": "auct_1aAmt",
      "1+B": "auct_1bAmt",
      "1+C": "auct_1cAmt",
      "1A": "auct_2aAmt",
      "1B": "auct_2bAmt",
      "1C": "auct_2cAmt",
      "2A": "auct_3aAmt",
      "2B": "auct_3bAmt",
      "2C": "auct_3cAmt",
      "3A": "auct_4aAmt",
      "3B": "auct_4bAmt",
      "3C": "auct_4cAmt",
      "\uB4F1\uC678": "auct_5dAmt"
    };
    if (gradeTagMap[cleanGrade]) {
      return gradeTagMap[cleanGrade];
    }
    if (cleanGrade.includes("1++")) return "auct_0bAmt";
    if (cleanGrade.includes("1+")) return "auct_1bAmt";
    if (cleanGrade.includes("1")) return "auct_2bAmt";
    if (cleanGrade.includes("2")) return "auct_3bAmt";
    if (cleanGrade.includes("3")) return "auct_4bAmt";
    if (cleanGrade.includes("\uB4F1\uC678")) return "auct_5dAmt";
    return "totalAuctAmt";
  }
  function findAbattCodeByName(inputNm) {
    if (!inputNm) return "0513";
    const cleanNm = inputNm.replace(/\s+/g, "");
    if (/^\d{4}$/.test(cleanNm)) {
      return cleanNm;
    }
    if (ABATT_CODE_MAP[cleanNm]) {
      return ABATT_CODE_MAP[cleanNm];
    }
    for (const [key, code] of Object.entries(ABATT_CODE_MAP)) {
      if (cleanNm.includes(key) || key.includes(cleanNm)) {
        return code;
      }
    }
    return "0513";
  }
