    const queryMatch = str.match(/[?&]id=([a-zA-Z0-9_-]+)/);
    if (queryMatch && queryMatch[1]) return queryMatch[1];
    const plainMatch = str.match(/^[a-zA-Z0-9_-]{20,}$/);
