  var DomainAppBridgeHelper = class {
    /**
     * DomainSpec 으로부터 App Building 메타데이터 매핑 Config 생성
     */
    static extractConfig(spec) {
      var _a;
      return {
        domainName: spec.domainName,
        sheetName: spec.sheetName,
        tableName: spec.tableName,
        primaryKey: spec.primaryKey,
        enabledSecurity: !!((_a = spec.security) == null ? void 0 : _a.enabled),
        supportedActions: ["CREATE", "READ", "UPDATE", "DELETE", "LIST", "METADATA"],
        defaultViewLayout: "TABLE",
        fields: spec.fields.map((f) => ({
          name: f.name,
          label: f.description || f.name,
          type: f.type,
          sqlType: f.sqlType,
          required: !!f.required,
          isSensitive: !!f.isSensitive,
          validation: f.validation
        }))
      };
    }
    /**
     * HTTP POST Body / GAS e.postData.contents 의 JSON 문자열 또는 객체 파싱 유틸
     */
    static parseRequest(rawInput) {
      if (!rawInput) return null;
      if (typeof rawInput === "object") return rawInput;
      try {
        return JSON.parse(rawInput);
      } catch (e) {
        return null;
      }
    }
    /**
     * 배열 데이터 기반 페이징 산출 유틸리티
     */
    static paginateList(items, pagination) {
      if (!items || !Array.isArray(items)) {
        return { pagedItems: [], paginationInfo: { page: 1, pageSize: 0, totalCount: 0, totalPages: 0 } };
      }
      const totalCount = items.length;
      if (!pagination || !pagination.page || !pagination.pageSize) {
        return {
          pagedItems: items,
          paginationInfo: { page: 1, pageSize: totalCount, totalCount, totalPages: 1 }
        };
      }
      const page = Math.max(1, pagination.page);
      const pageSize = Math.max(1, pagination.pageSize);
      const totalPages = Math.ceil(totalCount / pageSize) || 1;
      const startIndex = (page - 1) * pageSize;
      const pagedItems = items.slice(startIndex, startIndex + pageSize);
      return {
        pagedItems,
        paginationInfo: { page, pageSize, totalCount, totalPages }
      };
    }
  };

